numbers = [1, 3, 5, 7, 9, 11]
target = 7
low = 0
high = len(numbers) - 1
while low <= high:
    mid = (low + high) // 2
    if numbers[mid] == target:
        print(mid)
        break
    if numbers[mid] < target:
        low = mid + 1
    else:
        high = mid - 1

numbers = [7, 3, 5, 2]
for i in range(len(numbers)):
    min_index = i
    for j in range(i + 1, len(numbers)):
        if numbers[j] < numbers[min_index]:
            min_index = j
    numbers[i], numbers[min_index] = numbers[min_index], numbers[i]
print(numbers)

numbers = [5, 1, 4, 2]
for end in range(len(numbers) - 1, 0, -1):
    for i in range(end):
        if numbers[i] > numbers[i + 1]:
            numbers[i], numbers[i + 1] = numbers[i + 1], numbers[i]
print(numbers)

numbers = [1, 2, 4, 7, 11, 15]
target = 15
left = 0
right = len(numbers) - 1
while left < right:
    current = numbers[left] + numbers[right]
    if current == target:
        print(left, right)
        break
    if current < target:
        left += 1
    else:
        right -= 1

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(4))

